class ResultDiagram final:public QWidget {
public:
 enum Mode{Empty,ComplexPlane,NumberLine};Mode mode=Empty;double re=0,im=0;QString label;struct Interval{double low=-INFINITY,high=INFINITY;bool lowClosed=false,highClosed=false;};QVector<Interval> intervals;
 explicit ResultDiagram(QWidget*p=nullptr):QWidget(p){setMinimumHeight(qMax(170,fontMetrics().height()*6));hide();}
 void complex(double x,double y,QString caption){mode=ComplexPlane;re=x;im=y;label=caption;setAccessibleName(caption);show();update();}
 void line(QVector<Interval> ranges,QString caption){mode=NumberLine;intervals=ranges;label=caption;setAccessibleName(caption);show();update();}
protected:
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.setRenderHint(QPainter::Antialiasing);auto colors=TouchWorkbench::colors(WorkbenchViews::scopePalette(this));p.fillRect(rect(),colors.surface);p.setPen(colors.text);int labelHeight=fontMetrics().boundingRect(QRect(0,0,qMax(60,width()-16),1000),Qt::TextWordWrap,label).height()+8;int tickHeight=fontMetrics().height()+6;QRectF area=rect().adjusted(24,24,-24,-labelHeight-12);p.drawText(QRectF(6,height()-labelHeight,width()-12,labelHeight),Qt::AlignCenter|Qt::TextWordWrap,label);if(mode==ComplexPlane){QPointF c=area.center();p.drawLine(QPointF(area.left(),c.y()),QPointF(area.right(),c.y()));p.drawLine(QPointF(c.x(),area.top()),QPointF(c.x(),area.bottom()));double scale=std::max({std::abs(re),std::abs(im),1e-300})*1.3;QPointF z(c.x()+re/scale*area.width()/2,c.y()-im/scale*area.height()/2);p.setPen(QPen(colors.accent,2));p.drawLine(c,z);p.setBrush(QBrush(colors.accent));p.drawEllipse(z,4,4);p.drawText(QPointF(area.right()-14,c.y()-4),"Re");p.drawText(QPointF(c.x()+4,area.top()+10),"Im");}else if(mode==NumberLine){double low=-2,high=2;for(auto i:intervals){if(std::isfinite(i.low))low=std::min(low,i.low-1);if(std::isfinite(i.high))high=std::max(high,i.high+1);}double y=area.center().y();auto x=[&](double v){return area.left()+(v-low)/(high-low)*area.width();};p.drawLine(QPointF(area.left(),y),QPointF(area.right(),y));for(auto interval:intervals){double l=std::isfinite(interval.low)?x(interval.low):area.left(),h=std::isfinite(interval.high)?x(interval.high):area.right();p.setPen(QPen(colors.accent,5));p.drawLine(QPointF(l,y),QPointF(h,y));for(int end=0;end<2;++end){double v=end?interval.high:interval.low;if(!std::isfinite(v))continue;bool closed=end?interval.highClosed:interval.lowClosed;p.setPen(QPen(colors.accent,2));p.setBrush(closed?QBrush(colors.accent):QBrush(colors.surface));p.drawEllipse(QPointF(x(v),y),5,5);p.setPen(colors.text);p.drawText(QRectF(x(v)-55,y+10,110,tickHeight),Qt::AlignCenter,QString::number(v,'g',6));}}}}
};
