void GuidedWorkbench::updateFields(){const auto op=operation_->currentData().toString();auto visible=[this](const char*key,bool show){if(fields_.contains(key))fields_[key]->setVisible(show);};bool solve=op=="solve"||op=="inequality";visible("Variable / unknowns",guidedUsesVariables(op));visible("Order",op=="diff"||op=="diffpoint"||op=="partial");visible("Point",op=="newton"||op=="diffpoint"||op=="limit");bool bounds=op=="secant"||op=="definite"||op=="sum"||op=="product"||(solve&&bounded_->isChecked());visible("Lower bound",bounds);visible("Upper bound",bounds);visible("Direction",op=="limit");visible("Replacement",op=="substitute");bounded_->setVisible(solve);operationNote_->setVisible(op=="newton"||op=="secant"||op=="partial");}
void GuidedWorkbench::showResult(const CalcResult&r){resultCard_->setValue(r.ok?r.result:QString(),r.ok?r.serialized:QString(),r.resultApproximate);if(r.ok&&r.resultRepeatLength>0)resultCard_->math->setRecurringDigits(r.resultRepeatStart,r.resultRepeatLength,r.resultCopyValue.isEmpty()?r.serialized:r.resultCopyValue);if(auto*scroll=findChild<QScrollArea*>())QTimer::singleShot(0,this,[this,scroll]{scroll->ensureWidgetVisible(resultCard_,0,12);});}
void GuidedWorkbench::fieldsChanged(){if(onCancel)onCancel();++generation_;diagram_->hide();canonical_.clear();insert_->setEnabled(false);accept_->setEnabled(false);run_->setEnabled(true);run_->show();stop_->hide();output_->clear();resultCard_->setValue("","",false,WorkbenchViews::tr(translator_,"Calculate to see the result."));}
void GuidedWorkbench::cancel(){fieldsChanged();output_->setPlainText(localized(translator_,"Cancelled"));}
void GuidedWorkbench::setSelection(QString s,QString part){selectionSource_=s;selected_=part;expression_->setText(part.isEmpty()?s:part);}
void GuidedWorkbench::run(){
 if(!onInspect)return;if(auto*f=QApplication::focusWidget())f->clearFocus();QGuiApplication::inputMethod()->hide();QString e=expression_->text().trimmed(),x=variable_->text().trimmed(),op=operation_->currentData().toString();if(e.isEmpty())return;
 if(guidedUsesVariables(op)&&!QRegularExpression("^[a-z][a-z0-9_]*(,[a-z][a-z0-9_]*)*$").match(x).hasMatch()){output_->setPlainText(localized(translator_,"Use explicit variable names separated by commas."));return;}
 QString request;
 if(op=="solve"||op=="inequality"){QString equation=e;QString conditions=assumptions_->text().trimmed();if(bounded_->isChecked()){QString bounds="("+x+">=("+lower_->text()+")) && ("+x+"<=("+upper_->text()+"))";conditions=conditions.isEmpty()?bounds:"("+conditions+") && "+bounds;}if(!conditions.isEmpty()){if(!equation.contains(QRegularExpression("[=<>]")))equation="("+equation+")=0";equation="("+equation+") && ("+conditions+")";}request="solve("+equation+","+x+")";}
 else if(op=="multisolve")request="multisolve(["+e+"],["+x+"])";
 else if(op=="newton")request="newtonsolve("+e+","+point_->text()+","+x+",20,200)";
 else if(op=="secant")request="secantsolve("+e+","+lower_->text()+","+upper_->text()+","+x+",20,200)";
 else if(op=="diff"||op=="diffpoint") request="diff("+e+","+x+","+QString::number(order_->value())+")";
 else if(op=="partial"){request=e;for(const auto&variable:x.split(','))request="diff("+request+","+variable+","+QString::number(order_->value())+")";}
 else if(op=="integrate")request="integrate("+e+",undefined,undefined,"+x+")";
 else if(op=="definite")request="integrate("+e+","+lower_->text()+","+upper_->text()+","+x+")";
 else if(op=="limit")request="limit("+e+","+point_->text()+","+x+","+QString::number(side_->currentIndex()==1?-1:side_->currentIndex()==2?1:0)+")";
 else if(op=="sum"||op=="product")request=op+"("+e+","+lower_->text()+","+upper_->text()+","+x+")";
 else if(op=="evaluate")request=e;
 else if(op=="substitute")request="replace("+e+","+x+","+substitute_->text()+")";
 else request=(op=="factor"?QString("factorform"):op)+"("+e+")";
 const quint64 gen=++generation_;run_->setEnabled(false);run_->hide();stop_->show();output_->setPlainText(localized(translator_,"Calculating…"));auto context=std::make_shared<CalcContextSnapshot>();context->options.complexEnabled=domain_->currentIndex()==1;context->options.angle=0;if(op=="newton"||op=="secant")context->options.exact=false;context->assumptions={domain_->currentIndex()==0?QString("Real"):QString("Complex")};if(!assumptions_->text().trimmed().isEmpty())context->assumptions<<assumptions_->text().trimmed();QPointer<GuidedWorkbench> guard(this);
 onInspect(request,context,[guard,gen,op,request,e,x,context](CalcResult r){
  if(!guard||gen!=guard->generation_)return;
  if(r.ok&&op=="diffpoint"){QString substitution="replace(("+r.serialized+"),"+x+",("+guard->point_->text()+"))";guard->onInspect(substitution,context,[guard,gen](CalcResult atPoint){if(!guard||gen!=guard->generation_)return;guard->run_->setEnabled(true);guard->run_->show();guard->stop_->hide();guard->canonical_=atPoint.ok?atPoint.serialized:QString();guard->insert_->setEnabled(atPoint.ok);guard->accept_->setEnabled(atPoint.ok&&!guard->selected_.isEmpty());guard->showResult(atPoint);guard->output_->setPlainText(atPoint.ok?atPoint.result:panelTranslateOutput(atPoint.error,guard->translator_));});return;}
  guard->run_->setEnabled(true);guard->run_->show();guard->stop_->hide();guard->canonical_=r.ok?r.serialized:QString();guard->insert_->setEnabled(r.ok);guard->accept_->setEnabled(r.ok&&!guard->selected_.isEmpty());QString text=r.ok?r.result:panelTranslateOutput(r.error,guard->translator_);
  if(r.ok&&op=="integrate")text+="\n\n"+localized(guard->translator_,"Add an arbitrary integration constant; the displayed result is one antiderivative.");
  if(r.ok&&r.serialized.contains(request.section('(',0,0)+"("))text+="\n\n"+localized(guard->translator_,"The backend retained an unevaluated form; this is not a convergence or completeness proof.");
  if(r.ok&&(op=="newton"||op=="secant"))text+="\n\n"+localized(guard->translator_,"Numerical root from the chosen guesses; not a complete root set or a guaranteed bracket.");
  if(!guard->assumptions_->text().trimmed().isEmpty()&&op!="solve"&&op!="inequality")text+="\n\n"+localized(guard->translator_,"Conditions are recorded; only equation and inequality solving enforce these filters.");
  QStringList roots=scalarSolutions(r.serialized);if(r.ok&&(op=="solve"||op=="inequality"||op=="multisolve")){if(!roots.isEmpty()){text+="\n\n"+localized(guard->translator_,op=="multisolve"?"Solution components":"Root indices")+":";auto vars=x.split(',');for(int i=0;i<roots.size();++i)text+="\n"+(op=="multisolve"&&i<vars.size()?vars[i]:QString::number(i))+": "+roots[i];}if(op!="multisolve")showSolutions(static_cast<ResultDiagram*>(guard->diagram_),r.serialized,x,localized(guard->translator_,"Solution number line"),op!="inequality");}
  guard->showResult(r);guard->output_->setPlainText(text);
  if(!r.ok||!(op=="solve"||op=="newton"||op=="secant"||op=="multisolve"))return;
  QStringList residuals;if(op=="multisolve"){auto variables=x.split(',');if(roots.size()==variables.size()){auto equations=scalarSolutions('['+e+']');QStringList differences;for(auto equation:equations)differences<<equationResidual(equation);QString residual='['+differences.join(',')+']';for(int i=0;i<variables.size();++i)residual="replace("+residual+","+variables[i]+",("+roots[i]+"))";residuals<<residual;}}
  else{if(roots.isEmpty())roots<<r.serialized;for(auto root:roots){if(root.contains(x+'=')||root.contains(x+" ="))root=root.section('=',1).trimmed();residuals<<"replace(("+equationResidual(e)+"),"+x+",("+root+"))";}}
  if(residuals.isEmpty()||residuals.size()>32)return;QString expression='['+residuals.join(',')+']';
  guard->onInspect(expression,context,[guard,gen,text](CalcResult checked){if(!guard||gen!=guard->generation_)return;guard->output_->setPlainText(text+"\n\n"+localized(guard->translator_,"Substituted residuals (in displayed order)")+": "+(checked.ok?checked.result:panelTranslateOutput(checked.error,guard->translator_)));});
 });
}
QJsonObject GuidedWorkbench::saveState()const{return{{"assumptions",assumptions_->text()},{"bounded",bounded_->isChecked()},{"operation",operation_->currentData().toString()},{"expression",expression_->text()},{"variable",variable_->text()},{"point",point_->text()},{"lower",lower_->text()},{"upper",upper_->text()},{"replacement",substitute_->text()},{"order",order_->value()},{"domain",domain_->currentIndex()},{"side",side_->currentIndex()}};}
bool GuidedWorkbench::restoreState(const QJsonObject&o,QString*){for(const auto &k:{"expression","variable","point","lower","upper","replacement","assumptions"})if(o.value(k).toString().size()>4096)return false;assumptions_->setText(o.value("assumptions").toString());bounded_->setChecked(o.value("bounded").toBool());operation_->setCurrentIndex(qMax(0,operation_->findData(o.value("operation").toString())));expression_->setText(o.value("expression").toString());variable_->setText(o.value("variable").toString("x"));point_->setText(o.value("point").toString("0"));lower_->setText(o.value("lower").toString("0"));upper_->setText(o.value("upper").toString("1"));substitute_->setText(o.value("replacement").toString());order_->setValue(o.value("order").toInt(1));domain_->setCurrentIndex(qBound(0,o.value("domain").toInt(),1));side_->setCurrentIndex(qBound(0,o.value("side").toInt(),2));return true;}
