void DefinitionsPanel::setDefinitions(const QVector<CalcDefinition>&d){definitions_=d;populate();}
void DefinitionsPanel::populate(){QSignalBlocker b(list_);list_->clear();for(const auto&d:definitions_){auto*item=new QListWidgetItem((d.favorite?"★ ":"")+d.name,list_);item->setSizeHint(QSize(0,qMax(60,list_->fontMetrics().height()+30)));item->setToolTip(d.help);}}
